files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  display: grid;
  place-items: center;
  min-block-size: 100dvb;
  margin: 0;
  padding: 2em;
  background-color: #6dc1fd;
}

.game {
  inline-size: 600px;
  aspect-ratio: 1 / 1;
}
.field {
  fill: #5f0dee;
  stroke: #fd24af;
  stroke-width: 10;
}

line,
circle {
  stroke: #fff;
}
